// Is the rendered pack actually usable?
//
// The clips are generated by a model, so "the render succeeded" says nothing
// about whether a child hears a sentence or two files bolted together. Nobody
// is going to listen to 116 clips before every deploy, so the properties that
// make a splice work are measured instead.
//
// Skips cleanly when the pack has not been rendered -- an unrendered pack is a
// known state, not a failure.

import { readFileSync, existsSync, readdirSync } from 'node:fs';
import { execFileSync, spawnSync } from 'node:child_process';
import { join } from 'node:path';
import assert from 'node:assert';

const OUT = 'public/voice/words/v1';
const script = JSON.parse(readFileSync('tools/voice/words-script.json', 'utf8'));

if (!existsSync(join(OUT, 'index.json'))
    || !JSON.parse(readFileSync(join(OUT, 'index.json'), 'utf8')).ids.length) {
  console.log('\n(SKIPPED test-voice-pack: no pack rendered -- node tools/voice/render-words.mjs)\n');
  process.exit(0);
}
try { execFileSync('ffprobe', ['-version'], { stdio: 'ignore' }); }
catch { console.log('\n(SKIPPED test-voice-pack: ffprobe not installed)\n'); process.exit(0); }

let pass = 0, fail = 0;
const t = (name, fn) => {
  try { fn(); console.log(`  ok   ${name}`); pass++; }
  catch (e) { console.log(`  FAIL ${name}\n       ${e.message}`); fail++; }
};

const index = JSON.parse(readFileSync(join(OUT, 'index.json'), 'utf8'));
const probe = (id) => {
  const out = execFileSync('ffprobe', ['-v', 'error', '-show_entries',
    'format=duration', '-of', 'default=nw=1:nk=1', join(OUT, `${id}.mp3`)], { encoding: 'utf8' });
  return parseFloat(out.trim());
};

/** Leading and trailing silence, in seconds. A splice with silence on both
 *  sides of the join has an audible hole in the middle of the sentence. */
const edges = (id) => {
  // silencedetect reports on STDERR, not stdout -- execFileSync returns stdout,
  // so this silently read null and every splice check errored instead of running.
  const out = spawnSync('ffmpeg', ['-i', join(OUT, `${id}.mp3`), '-af',
    'silencedetect=noise=-45dB:d=0.05', '-f', 'null', '-'], { encoding: 'utf8' }).stderr || '';
  const dur = probe(id);
  const starts = [...out.matchAll(/silence_start: ([\d.]+)/g)].map((m) => +m[1]);
  const ends = [...out.matchAll(/silence_end: ([\d.]+)/g)].map((m) => +m[1]);
  const lead = ends.length && starts.length && starts[0] < 0.02 ? ends[0] : 0;
  const tail = starts.length && starts[starts.length - 1] > ends[ends.length - 1]
    ? dur - starts[starts.length - 1] : 0;
  return { lead, tail, dur };
};

console.log('\nthe pack is complete and playable');

/* NOTE ON SCOPE, because it cost me an hour. This file tests the WORDS pack
 * (public/voice/words/v1, from tools/voice/words-script.json) — the one /words
 * speaks from. It has never covered the GAME pack that Pip speaks from in
 * /play, which is a separate pack built from tools/voice/manifest.js. That one
 * is now covered by test-voice-game.mjs. The two are easy to confuse: both are
 * "the voice pack", both live under public/voice, and this suite's name
 * suggests it covers both. It does not. */

t('every line in the script rendered', () => {
  const missing = script.lines.map((l) => l.id).filter((id) => !index.ids.includes(id));
  assert.equal(missing.length, 0, `missing: ${missing.slice(0, 5).join(', ')}`);
});

t('the index claims nothing that is not on disk', () => {
  const onDisk = new Set(readdirSync(OUT).filter((f) => f.endsWith('.mp3')).map((f) => f.slice(0, -4)));
  const phantom = index.ids.filter((id) => !onDisk.has(id));
  assert.equal(phantom.length, 0,
    `${phantom.length} clip(s) claimed but absent -- a child would hear silence mid-sentence`);
});

t('no clip is empty or truncated', () => {
  const bad = index.ids.map((id) => [id, probe(id)]).filter(([, d]) => !(d > 0.25));
  assert.equal(bad.length, 0, `too short: ${bad.slice(0, 4).map(([i, d]) => `${i}=${d}s`).join(', ')}`);
});

t('no clip exceeds the player cap', () => {
  // speech.js gives up on a clip after 9s. Anything longer is cut off mid-word.
  const over = index.ids.map((id) => [id, probe(id)]).filter(([, d]) => d >= 9);
  assert.equal(over.length, 0, `over 9s: ${over.map(([i, d]) => `${i}=${d.toFixed(1)}s`).join(', ')}`);
});

t('the pack records which voice and model made it', () => {
  // Two tools write index.json; the id-list refresh used to erase this. When a
  // clip sounds wrong, "which voice was this rendered with" is the first
  // question, and a pack that cannot answer it is a pack you have to re-render
  // blind.
  assert(index.voice, 'no voice recorded in index.json');
  assert(index.model, 'no model recorded in index.json');
});

console.log('\nthe splice has no audible seam');

t('invitations do not trail off into silence', () => {
  // A phrase that ends with a long pause puts a hole before the word.
  const asks = index.ids.filter((id) => id.startsWith('ask-'));
  const bad = asks.map((id) => [id, edges(id)]).filter(([, e]) => e.tail > 0.35);
  assert.equal(bad.length, 0,
    `trailing silence: ${bad.map(([i, e]) => `${i}=${e.tail.toFixed(2)}s`).join(', ')}`);
});

t('words do not begin with a long pause', () => {
  const words = index.ids.filter((id) => id.startsWith('w-')).slice(0, 30);
  const bad = words.map((id) => [id, edges(id)]).filter(([, e]) => e.lead > 0.35);
  assert.equal(bad.length, 0,
    `leading silence: ${bad.map(([i, e]) => `${i}=${e.lead.toFixed(2)}s`).join(', ')}`);
});

t('the joined gap stays under a quarter second', () => {
  // The perceptual budget. Past roughly 250ms a listener hears two files.
  const pairs = [['ask-gap', 'w-rope'], ['ask-dark', 'w-lamp'], ['ask-carry', 'w-box']]
    .filter(([a, b]) => index.ids.includes(a) && index.ids.includes(b));
  assert(pairs.length, 'no representative pair found in the pack');
  for (const [a, b] of pairs) {
    const gap = edges(a).tail + edges(b).lead;
    assert(gap < 0.25, `${a} + ${b} leaves a ${(gap * 1000).toFixed(0)}ms hole`);
  }
});

console.log('\nthe voice is unhurried, as directed');

t('speech is at child-directed rate, not adult-directed', () => {
  // Measured in SYLLABLES per second, because that is the unit the child-directed
  // speech literature uses and because words/sec flatters a line like "Can you
  // say" where every word is one syllable. Adult-directed running speech sits
  // around 5-6 syll/sec; adults slow to roughly 3-4 when speaking to a toddler.
  //
  // The band is taken from that, NOT tuned until the render passed -- the first
  // render came out at 5.5 syll/sec, which is a stranger talking over a child's
  // head. The lower bound matters just as much: dragging below 3 reads as
  // patronising and loses a toddler's attention as fast as rushing does.
  const syllables = (text) => text.toLowerCase().split(/\s+/).reduce((n, w) => {
    const c = w.replace(/[^a-z]/g, '').replace(/e$/, '');
    const groups = c.match(/[aeiouy]+/g);
    return n + Math.max(groups ? groups.length : 0, c ? 1 : 0);
  }, 0);

  const asks = index.ids.filter((id) => id.startsWith('ask-'));
  const rates = asks.map((id) => {
    const line = script.lines.find((l) => l.id === id);
    const e = edges(id);
    return syllables(line.text) / Math.max(e.dur - e.lead - e.tail, 0.1);
  });
  const mean = rates.reduce((a, b) => a + b, 0) / rates.length;
  console.log(`       (${mean.toFixed(2)} syllables/sec)`);
  assert(mean < 4.3, `${mean.toFixed(2)} syll/sec is adult-directed pace`);
  assert(mean > 3.0, `${mean.toFixed(2)} syll/sec is dragging -- patronising, not gentle`);
});

t('a word said alone is given room', () => {
  const words = index.ids.filter((id) => id.startsWith('w-')).slice(0, 20);
  const durs = words.map((id) => probe(id));
  const mean = durs.reduce((a, b) => a + b, 0) / durs.length;
  assert(mean > 0.45, `${mean.toFixed(2)}s per word is clipped, not spoken clearly`);
});

console.log('\nthe pack is small enough to ship');

t('the whole pack is under 3 MB', () => {
  const bytes = readdirSync(OUT).filter((f) => f.endsWith('.mp3'))
    .reduce((a, f) => a + readFileSync(join(OUT, f)).length, 0);
  const mb = bytes / 1024 / 1024;
  console.log(`       (${mb.toFixed(2)} MB for ${index.ids.length} clips)`);
  assert(mb < 3, `${mb.toFixed(1)} MB is too much to fetch on a phone`);
});

console.log(`\n${pass} passed, ${fail} failed\n`);
process.exit(fail ? 1 : 0);
